//! Supertonic MNN parity spike: run the 4 TTS .mnn models through the
//! multi-input session API and diff against Python reference dumps.
//!
//! Ref dumps: /tmp/supertonic-ref (generated by dump_ref.py, seed=2026).
//! Models: ~/.cache/supertonic-mnn/v3/mnn_models/fp16/
//!
//! Usage: cargo run --example supertonic_parity --features mnn-multi

use std::path::Path;

fn read_npy(path: &Path) -> (Vec<i32>, Vec<f32>, Vec<i64>) {
    let bytes = std::fs::read(path).expect("npy read");
    assert_eq!(&bytes[0..6], b"\x93NUMPY", "magic");
    let ver_major = bytes[6];
    let hdr_len = if ver_major == 1 {
        u16::from_le_bytes([bytes[8], bytes[9]]) as usize
    } else {
        u32::from_le_bytes([bytes[8], bytes[9], bytes[10], bytes[11]]) as usize
    };
    let off = if ver_major == 1 { 10 } else { 12 };
    let header = String::from_utf8_lossy(&bytes[off..off + hdr_len]).to_string();
    let dtype_i32 = header.contains("i4") || header.contains("int32");
    // parse shape tuple
    let shape_start = header.find("'shape':").expect("shape key") + 8;
    let shape_str = &header[shape_start..];
    let open = shape_str.find('(').expect("open paren");
    let close = shape_str.find(')').expect("close paren");
    let shape: Vec<i64> = shape_str[open + 1..close]
        .split(',')
        .filter_map(|s| s.trim().parse::<i64>().ok())
        .collect();
    let data = &bytes[off + hdr_len..];
    let mut i32s = Vec::new();
    let mut f32s = Vec::new();
    if dtype_i32 {
        for chunk in data.chunks_exact(4) {
            i32s.push(i32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]));
        }
    } else {
        for chunk in data.chunks_exact(4) {
            f32s.push(f32::from_le_bytes([chunk[0], chunk[1], chunk[2], chunk[3]]));
        }
    }
    (i32s, f32s, shape)
}

fn load_f32(name: &str) -> (Vec<f32>, Vec<i64>) {
    let (i, f, s) = read_npy(Path::new("/tmp/supertonic-ref").join(format!("{name}.npy")).as_path());
    assert!(i.is_empty(), "{name} expected float");
    (f, s)
}

fn load_i32(name: &str) -> (Vec<i32>, Vec<i64>) {
    let (i, f, s) = read_npy(Path::new("/tmp/supertonic-ref").join(format!("{name}.npy")).as_path());
    assert!(f.is_empty(), "{name} expected int");
    (i, s)
}

fn diff(name: &str, a: &[f32], b: &[f32]) -> (f32, f32) {
    assert_eq!(a.len(), b.len(), "{name} length");
    let mut max_abs = 0f32;
    let mut sum_sq = 0f64;
    let mut ref_sq = 0f64;
    for (x, y) in a.iter().zip(b.iter()) {
        max_abs = max_abs.max((x - y).abs());
        sum_sq += ((x - y) as f64).powi(2);
        ref_sq += (*y as f64).powi(2);
    }
    let rel = (sum_sq.sqrt()) / (ref_sq.sqrt().max(1e-9));
    println!("{name}: max_abs={max_abs:.6} rel_rmse={rel:.6}");
    (max_abs, rel as f32)
}

fn main() {
    let model_dir = std::env::var("SUPERTONIC_MODEL_DIR")
        .unwrap_or_else(|_| format!("{}/.cache/supertonic-mnn/v3/mnn_models/fp16", std::env::var("HOME").unwrap()));
    let cfg = ocr_rs::mnn::InferenceConfig::new()
        .with_threads(4)
        .with_precision(ocr_rs::mnn::PrecisionMode::Low);

    // 1. duration predictor
    let (text_ids, ids_shape) = load_i32("text_ids");
    let (text_mask, mask_shape) = load_f32("text_mask");
    let (style_dp, sdp_shape) = load_f32("style_dp");
    let mut dp = ocr_rs::mnn::MultiSession::from_file_named(format!("{model_dir}/duration_predictor.mnn"), Some(cfg.clone()), &["text_ids", "style_dp", "text_mask"], &["duration"]).unwrap();
    dp.set_input("text_ids", &(ids_shape.iter().map(|&d| d as i32).collect::<Vec<_>>()), ocr_rs::mnn::MultiInput::I32(&text_ids)).unwrap();
    dp.set_input("text_mask", &(mask_shape.iter().map(|&d| d as i32).collect::<Vec<_>>()), ocr_rs::mnn::MultiInput::F32(&text_mask)).unwrap();
    dp.set_input("style_dp", &(sdp_shape.iter().map(|&d| d as i32).collect::<Vec<_>>()), ocr_rs::mnn::MultiInput::F32(&style_dp)).unwrap();
    dp.run().unwrap();
    let dur = dp.output_f32("duration").unwrap();
    let (dur_ref, _) = load_f32("dur");
    let (dur_max, dur_rel) = diff("dur", &dur, &dur_ref);

    // 2. text encoder
    let (style_ttl, sttl_shape) = load_f32("style_ttl");
    let mut enc = ocr_rs::mnn::MultiSession::from_file_named(format!("{model_dir}/text_encoder.mnn"), Some(cfg.clone()), &["text_ids", "style_ttl", "text_mask"], &["text_emb"]).unwrap();
    enc.set_input("text_ids", &(ids_shape.iter().map(|&d| d as i32).collect::<Vec<_>>()), ocr_rs::mnn::MultiInput::I32(&text_ids)).unwrap();
    enc.set_input("style_ttl", &(sttl_shape.iter().map(|&d| d as i32).collect::<Vec<_>>()), ocr_rs::mnn::MultiInput::F32(&style_ttl)).unwrap();
    enc.set_input("text_mask", &(mask_shape.iter().map(|&d| d as i32).collect::<Vec<_>>()), ocr_rs::mnn::MultiInput::F32(&text_mask)).unwrap();
    enc.run().unwrap();
    let emb = enc.output_f32("text_emb").unwrap();
    let (emb_ref, _) = load_f32("est_0_in_text_emb");
    let (emb_max, emb_rel) = diff("text_emb", &emb, &emb_ref);

    // 3. vector estimator — replay all 5 steps
    let (emb, emb_shape) = load_f32("est_0_in_text_emb");
    let mut vest = ocr_rs::mnn::MultiSession::from_file_named(format!("{model_dir}/vector_estimator.mnn"), Some(cfg.clone()), &["noisy_latent", "text_emb", "style_ttl", "latent_mask", "text_mask", "current_step", "total_step"], &["denoised_latent"]).unwrap();
    for step in 0..5 {
        let (noisy, n_shape) = if step == 0 {
            load_f32("est_0_in_noisy_latent")
        } else {
            load_f32(&format!("est_{}_out", step - 1))
        };
        let (cur, cur_shape) = load_f32(&format!("est_{step}_in_current_step"));
        let (tot, tot_shape) = load_f32(&format!("est_{step}_in_total_step"));
        let (lmask, lmask_shape) = load_f32(&format!("est_{step}_in_latent_mask"));
        let dims = |s: &Vec<i64>| s.iter().map(|&d| d as i32).collect::<Vec<_>>();
        vest.set_input("noisy_latent", &dims(&n_shape), ocr_rs::mnn::MultiInput::F32(&noisy)).unwrap();
        vest.set_input("text_emb", &dims(&emb_shape), ocr_rs::mnn::MultiInput::F32(&emb)).unwrap();
        vest.set_input("style_ttl", &dims(&sttl_shape), ocr_rs::mnn::MultiInput::F32(&style_ttl)).unwrap();
        vest.set_input("latent_mask", &dims(&lmask_shape), ocr_rs::mnn::MultiInput::F32(&lmask)).unwrap();
        vest.set_input("text_mask", &dims(&mask_shape), ocr_rs::mnn::MultiInput::F32(&text_mask)).unwrap();
        vest.set_input("current_step", &dims(&cur_shape), ocr_rs::mnn::MultiInput::F32(&cur)).unwrap();
        vest.set_input("total_step", &dims(&tot_shape), ocr_rs::mnn::MultiInput::F32(&tot)).unwrap();
        vest.run().unwrap();
        let out = vest.output_f32("denoised_latent").unwrap();
        let (out_ref, _) = load_f32(&format!("est_{step}_out"));
        diff(&format!("step_{step}"), &out, &out_ref);
    }

    // 4. vocoder
    let (latent, l_shape) = load_f32("est_4_out");
    let mut voc = ocr_rs::mnn::MultiSession::from_file_named(format!("{model_dir}/vocoder.mnn"), Some(cfg), &["latent"], &["wav_tts"]).unwrap();
    voc.set_input("latent", &(l_shape.iter().map(|&d| d as i32).collect::<Vec<_>>()), ocr_rs::mnn::MultiInput::F32(&latent)).unwrap();
    voc.run().unwrap();
    let shape = voc.output_shape("wav_tts").unwrap();
    println!("wav shape: {shape:?}");
    let wav = voc.output_f32("wav_tts").unwrap();
    let (wav_ref, _) = load_f32("wav");
    if let Ok(path) = std::env::var("SUPERTONIC_DUMP_WAV") {
        let sr = 44100u32;
        let data: Vec<u8> = wav.iter().flat_map(|s| (((*s).clamp(-1.0, 1.0) * 32767.0) as i16).to_le_bytes()).collect();
        let mut w = Vec::new();
        w.extend_from_slice(b"RIFF"); w.extend_from_slice(&((36 + data.len()) as u32).to_le_bytes()); w.extend_from_slice(b"WAVEfmt ");
        w.extend_from_slice(&16u32.to_le_bytes()); w.extend_from_slice(&1u16.to_le_bytes()); w.extend_from_slice(&1u16.to_le_bytes());
        w.extend_from_slice(&sr.to_le_bytes()); w.extend_from_slice(&(sr * 2).to_le_bytes()); w.extend_from_slice(&2u16.to_le_bytes()); w.extend_from_slice(&16u16.to_le_bytes());
        w.extend_from_slice(b"data"); w.extend_from_slice(&(data.len() as u32).to_le_bytes()); w.extend_from_slice(&data);
        std::fs::write(&path, w).unwrap();
        println!("wrote {path}");
    }
    let (wav_max, wav_rel) = diff("wav", &wav, &wav_ref);
    println!("wav absmax: {:.4}", wav.iter().fold(0f32, |m, &x| m.max(x.abs())));
    // MNN version drift (py wheel 3.5 vs prebuilt 3.6) allows small numeric
    // differences; require close agreement per stage.
    let ok = emb_max < 1e-4
        && dur_rel < 0.02
        && wav_rel < 0.05
        && wav_max < 0.1;
    println!(
        "thresholds: emb_max<1e-4 dur_rel<0.02 wav_rel<0.05 wav_max<0.1 -> {}",
        if ok { "PARITY OK" } else { "PARITY FAIL" }
    );
    if !ok {
        std::process::exit(1);
    }
}
